var t=[{title:`Vlákna typu I`,text:`Často se nazývají pomalá a obvykle se stahují pomaleji, vytvářejí menší maximální sílu na vlákno a dobře odolávají únavě. Účinně využívají aerobní metabolismus a odvádějí velkou část práce při dlouhých nebo opakovaných aktivitách nízké intenzity, jako je chůze a stálá jízda na kole.`},{title:`Vlákna typu II`,text:`Obecně se nazývají rychlá a dokážou vytvářet sílu rychleji a mohutněji. U lidí mají vlákna typu IIa velkou kapacitu pro oxidační i glykolytickou tvorbu energie, zatímco vlákna typu IIx bývají rychlejší a unaví se snáze. Poměr typů vláken se liší podle svalu i podle člověka.`},{title:`Zapojování podle nároků`,text:`Princip velikosti popisuje, jak váš nervový systém obecně zapojuje nejdřív menší motorické jednotky s nižším prahem a s rostoucí potřebnou silou přidává jednotky s vyšším prahem. Těžké zdvihy zapojují motorické jednotky s vysokým prahem hned zkraje. Lehčí zátěže je mohou zapojit také, jak narůstá únava, pokud úsilí dosáhne dostatečné úrovně. To pomáhá vysvětlit, proč svaly mohou růst v poměrně širokém rozsahu zátěží.`},{title:`Co trénink mění`,text:`Vytrvalostní trénink zlepšuje vaše aerobní zázemí a odolnost proti únavě. Odporový a výbušný trénink zlepšují tvorbu síly a mohou budovat svaly. Některé vlastnosti vláken se tréninkem mění, ale výsledky ovlivňují genetika, tréninková historie a věk, takže označovat někoho za „rychlého“ nebo „pomalého“ typu je zavádějící.`},{title:`Příklad`,text:`40sekundová série dřepů s vlastní vahou a těžká série dřepů se zátěží o pěti opakováních zatěžují váš nervosvalový systém odlišně. Obě mohou být užitečné, ale série se zátěží cvičí vytváření vysoké síly specifičtěji. Nemusíte testovat své složení vláken, abyste sestavili úplný program. Opakování, odpočinek a kondiční práci volte podle požadované adaptace a podle toho, jak dobře se pohybujete, ne podle označení typu vlákna, které nikdo neověřil.`}];var a=[{label:`Odporový trénink a kontinuum opakování`,url:`https://pubmed.ncbi.nlm.nih.gov/33671664/`},{label:`Stanovisko ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:t,sources:a};export{n as default,t as sections,a as sources};